/* 测试：真实Ledger与Commerce交易，检查半笔、非法重复、预留及恢复，不使用UI文字替代库存事实。 */
using System;
using System.Linq;
using Ossastra.Inventory;
using Ossastra.Commerce;
using Ossastra.CharacterCore;
using Ossastra.CharacterCore.Abilities;

sealed class AccessPolicy : ICommerceAccessPolicy
{
    public bool Allowed=true;
    public long Generation=1;
    public Func<CommerceAccess> BeforeCheck;
    public CommerceAccess Check(string actorId,string merchantId,long sessionGeneration)
        =>BeforeCheck?.Invoke()??new CommerceAccess(Allowed,Allowed?null:"不可访问",Generation,new[]{"team","safe"},"team","team",new[]{"team","safe"});
}
static class Program
{
    static int failed,passed;
    static void Assert(bool condition,string reason){if(!condition)throw new Exception(reason);}
    static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
    static (InventoryLedger ledger,CommerceEconomy economy,AccessPolicy access) Setup(int width=4)
    {
        var ledger=new InventoryLedger();
        ledger.Register(new InventoryDefinition("trade-coin",1,1,999999));
        ledger.Register(new InventoryDefinition("food",1,1,10));
        ledger.Register(new InventoryDefinition("large",2,1,1));
        ledger.AddContainer(new InventoryContainer("team",width,1));
        ledger.AddContainer(new InventoryContainer("safe",2,1,true));
        var access=new AccessPolicy();var economy=new CommerceEconomy(ledger,access);
        economy.RegisterMerchant(new MerchantDefinition("sample",new[]{new MerchantGoods("food",10,4,5),new MerchantGoods("large",5,2,2)},30),"shop-a");
        return(ledger,economy,access);
    }
    static long Count(InventoryLedger ledger,string definition)=>ledger.Items.Where(i=>i.DefinitionId==definition).Sum(i=>(long)i.Quantity);
    static InventoryLedger MaximumStackFixture()
    {
        var ledger=new InventoryLedger();ledger.Register(new InventoryDefinition("max-stack",1,1,int.MaxValue));
        ledger.AddContainer(new InventoryContainer("team",2,1));ledger.AddContainer(new InventoryContainer("safe",1,1));return ledger;
    }
    static TradeReceipt Buy(CommerceEconomy economy,string definition="food",int quantity=1,string merchant="shop-a",Guid? request=null)
    {var quote=economy.QuotePurchase("hero",merchant,definition,quantity,1);Assert(quote.Ok,quote.Reason);return economy.Execute(new TradeCommand(request??Guid.NewGuid(),quote.Quote));}
    static void Main(string[] args)
    {
        if(args.Length>0){Environment.ExitCode=EconomicProcessProof.Run(args);return;}
        Test("buy_multiple_commits_currency_goods_stock_together",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",30);var r=Buy(s.economy,quantity:2);Assert(r.Ok,r.Reason);Assert(Count(s.ledger,"trade-coin")==10&&Count(s.ledger,"food")==2&&s.economy.Merchant("shop-a").stock.Single(x=>x.definitionId=="food").quantity==3,"半笔买入");});
        Test("full_purchase_rejection_does_not_charge",()=>{var s=Setup(1);s.ledger.Grant("team","trade-coin",30);var r=Buy(s.economy);Assert(!r.Ok&&Count(s.ledger,"trade-coin")==30&&Count(s.ledger,"food")==0,"满包却扣币或给物");});
        Test("spent_coin_stack_releases_delivery_space",()=>{var s=Setup(1);s.ledger.Grant("team","trade-coin",10);Assert(Buy(s.economy).Ok&&Count(s.ledger,"trade-coin")==0&&Count(s.ledger,"food")==1,"未按最终状态试算");});
        Test("sell_only_selected_instance_quantity",()=>{var s=Setup();s.ledger.Grant("team","food",15);var selected=s.ledger.Items.Single(i=>i.Quantity==5);var quote=s.economy.QuoteSale("hero","shop-a",selected.Id,2,1);Assert(quote.Ok,quote.Reason);var r=s.economy.Execute(new TradeCommand(Guid.NewGuid(),quote.Quote));Assert(r.Ok&&s.ledger.Find(selected.Id).Quantity==3&&Count(s.ledger,"trade-coin")==8,"出售了错误实例/数量");});
        Test("sale_without_refund_space_is_atomic",()=>{var s=Setup(1);s.ledger.Grant("team","food",5);var id=s.ledger.Items[0].Id;var q=s.economy.QuoteSale("hero","shop-a",id,1,1);var r=s.economy.Execute(new TradeCommand(Guid.NewGuid(),q.Quote));Assert(!r.Ok&&s.ledger.Find(id).Quantity==5&&Count(s.ledger,"trade-coin")==0,"退款无空间形成半笔");});
        Test("reserved_after_quote_rejected_without_mutation",()=>{var s=Setup();s.ledger.Grant("team","food",3);var id=s.ledger.Items[0].Id;var q=s.economy.QuoteSale("hero","shop-a",id,1,1);s.ledger.Reserve(id,1,Guid.NewGuid());var r=s.economy.Execute(new TradeCommand(Guid.NewGuid(),q.Quote));Assert(!r.Ok&&Count(s.ledger,"food")==3,"卖掉动作预留");});
        Test("access_generation_changes_reject_old_quote",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",20);var q=s.economy.QuotePurchase("hero","shop-a","food",1,1);s.access.Generation++;var r=s.economy.Execute(new TradeCommand(Guid.NewGuid(),q.Quote));Assert(!r.Ok&&Count(s.ledger,"trade-coin")==20,"旧访问报价仍成交");});
        Test("same_request_replay_does_not_charge_again",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",30);var q=s.economy.QuotePurchase("hero","shop-a","food",1,1);var command=new TradeCommand(Guid.NewGuid(),q.Quote);Assert(s.economy.Execute(command).Ok,"首次失败");Assert(s.economy.Execute(command).Ok&&Count(s.ledger,"trade-coin")==20&&Count(s.ledger,"food")==1,"重放重复扣费");});
        Test("same_id_different_content_rejected",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",30);var id=Guid.NewGuid();Assert(Buy(s.economy,request:id).Ok,"首次失败");var q=s.economy.QuotePurchase("hero","shop-a","food",2,1);Assert(!s.economy.Execute(new TradeCommand(id,q.Quote)).Ok&&Count(s.ledger,"food")==1,"请求ID内容冲突未拒绝");});
        Test("subscriber_throw_cannot_undo_trade_or_duplicate",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",20);int seen=0;s.ledger.Changed+=()=>{Assert(s.economy.Merchant("shop-a").stock.First(x=>x.definitionId=="food").quantity==4,"通知看见半笔");throw new Exception("observer");};s.economy.Changed+=()=>seen++;var r=Buy(s.economy);Assert(r.Ok&&Count(s.ledger,"food")==1&&seen==1,"通知异常反转交易");});
        Test("same_template_two_instances_independent_restock",()=>{var s=Setup();s.economy.RegisterMerchant(new MerchantDefinition("sample",new[]{new MerchantGoods("food",10,4,5),new MerchantGoods("large",5,2,2)},30),"shop-b");s.ledger.Grant("team","trade-coin",100);Assert(Buy(s.economy).Ok,"买入失败");Assert(s.economy.Merchant("shop-b").stock.First(x=>x.definitionId=="food").quantity==5,"模板共享库存");s.economy.Advance(30);Assert(s.economy.Merchant("shop-a").stock.First(x=>x.definitionId=="food").quantity==5,"补货未到目标");});
        Test("duplicate_merchant_id_is_diagnostic",()=>{var s=Setup();bool rejected=false;try{s.economy.RegisterMerchant(new MerchantDefinition("sample",new[]{new MerchantGoods("food",10,4,5)},30),"shop-a");}catch(ArgumentException){rejected=true;}Assert(rejected,"重复ID静默共享");});
        Test("capture_is_detached_and_restore_atomic",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",30);Buy(s.economy);var snapshot=s.economy.Capture();Buy(s.economy);Assert(snapshot.inventory.items.Where(i=>i.definitionId=="food").Sum(i=>i.quantity)==1,"捕获仍引用活账本");var target=Setup();var r=target.economy.Restore(snapshot);Assert(r.Ok&&Count(target.ledger,"food")==1&&Count(target.ledger,"trade-coin")==20,"恢复失败");snapshot.inventory.items[0].quantity=-2;Assert(!target.economy.Restore(snapshot).Ok&&Count(target.ledger,"food")==1,"非法恢复污染现账本");});
        Test("restored_receipt_prevents_replay_and_refresh_clock_survives",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",30);var q=s.economy.QuotePurchase("hero","shop-a","food",1,1);var command=new TradeCommand(Guid.NewGuid(),q.Quote);s.economy.Execute(command);s.economy.Advance(20);var target=Setup();Assert(target.economy.Restore(s.economy.Capture()).Ok,"恢复失败");Assert(!target.economy.Execute(command).Ok&&Count(target.ledger,"food")==1,"旧会话请求恢复后重放");target.economy.Advance(9);Assert(target.economy.Merchant("shop-a").stock.First(x=>x.definitionId=="food").quantity==4,"重启自动补满");target.economy.Advance(1);Assert(target.economy.Merchant("shop-a").stock.First(x=>x.definitionId=="food").quantity==5,"模拟刷新时钟丢失");});
        Test("final_access_check_reservation_change_rejects_candidate",()=>{var s=Setup();s.ledger.Grant("team","food",3);var id=s.ledger.Items[0].Id;var quote=s.economy.QuoteSale("hero","shop-a",id,1,1);int calls=0;s.access.BeforeCheck=()=>{if(++calls==2)s.ledger.Reserve(id,1,Guid.NewGuid());return new CommerceAccess(true,null,1,new[]{"team","safe"},"team","team",new[]{"team","safe"});};var receipt=s.economy.Execute(new TradeCommand(Guid.NewGuid(),quote.Quote));Assert(!receipt.Ok&&Count(s.ledger,"food")==3&&Count(s.ledger,"trade-coin")==0,"最终预留变化未重验");});
        Test("container_registration_invalidates_existing_quote",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",20);var quote=s.economy.QuotePurchase("hero","shop-a","food",1,1);s.ledger.AddContainer(new InventoryContainer("late",1,1));var receipt=s.economy.Execute(new TradeCommand(Guid.NewGuid(),quote.Quote));Assert(!receipt.Ok&&Count(s.ledger,"trade-coin")==20,"容器注册未更新库存世代");});
        Test("restore_counter_overflow_never_changes_ledger",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",20);var bad=s.economy.Capture();bad.inventory.items[0].quantity=7;bad.inventory.accessGeneration=long.MaxValue;var result=s.economy.Restore(bad);Assert(!result.Ok&&Count(s.ledger,"trade-coin")==20,"恢复计数溢出后留下半本账");});
        Test("equipment_resources_restore_without_free_refill",()=>{var s=Setup();s.ledger.Register(new InventoryDefinition("blade",1,1,1,InventoryHand.Right));var item=new EquipmentItemState("blade-id","blade",OffhandKind.Other,1);item.Wear(Guid.NewGuid());item.Runtime.Tick(2,true);item.Runtime.Cooldowns.Commit("skill-a",Guid.NewGuid(),item.Runtime.Clock(AbilityCooldownPolicy.WhileEquipped),8);item.Runtime.Magazine.Consume(Guid.NewGuid(),2);item.Runtime.Frost.Spend(1,2);item.Runtime.SkillSelections[0]="skill-a";s.ledger.Grant("team","blade",1,item);var snapshot=s.economy.Capture();var target=Setup();target.ledger.Register(new InventoryDefinition("blade",1,1,1,InventoryHand.Right));var restored=target.economy.Restore(snapshot);Assert(restored.Ok,restored.Reason);var actual=target.ledger.Find("blade-id").Equipment;Assert(actual.Durability==0&&actual.Runtime.Magazine.Count==3&&actual.Runtime.Frost.Current==2&&actual.Runtime.Cooldowns.Remaining("skill-a",2)==8&&actual.Runtime.SkillSelections[0]=="skill-a","重启免费刷新装备资源");item.Runtime.Magazine.Consume(Guid.NewGuid(),2);Assert(actual.Runtime.Magazine.Count==3,"恢复payload仍引用旧装备");});
        Test("equipment_resource_change_during_prepare_invalidates_trade",()=>{var s=Setup();s.ledger.Register(new InventoryDefinition("blade",1,1,1,InventoryHand.Right));var item=new EquipmentItemState("blade-id","blade",OffhandKind.Other,5);s.ledger.Grant("team","blade",1,item);s.ledger.Grant("team","trade-coin",20);var quote=s.economy.QuotePurchase("hero","shop-a","food",1,1);int calls=0;s.access.BeforeCheck=()=>{if(++calls==2)item.Wear(Guid.NewGuid());return new CommerceAccess(true,null,1,new[]{"team","safe"},"team","team",new[]{"team","safe"});};var receipt=s.economy.Execute(new TradeCommand(Guid.NewGuid(),quote.Quote));Assert(!receipt.Ok&&Count(s.ledger,"trade-coin")==20,"候选提交重置/忽略活payload变化");});
        Test("malformed_restore_missing_definition_and_duplicate_identity_is_atomic",()=>{var s=Setup();s.ledger.Grant("team","food",1);var invalid=s.economy.Capture();invalid.inventory.items[0].definitionId="unknown";Assert(!s.economy.Restore(invalid).Ok&&Count(s.ledger,"food")==1,"缺定义被静默丢弃");invalid=s.economy.Capture();invalid.inventory.items=new[]{invalid.inventory.items[0],invalid.inventory.items[0]};Assert(!s.economy.Restore(invalid).Ok&&Count(s.ledger,"food")==1,"重复ID部分恢复");});
        Test("invalid_prices_quantities_and_old_restock_quote_reject",()=>{var s=Setup();Assert(!s.economy.QuotePurchase("hero","shop-a","food",0,1).Ok&&!s.economy.QuoteSale("hero","shop-a","missing",1,1).Ok,"非法数量或来源报价");s.ledger.Grant("team","trade-coin",100);var q=s.economy.QuotePurchase("hero","shop-a","food",1,1);s.economy.Advance(30);Assert(!s.economy.Execute(new TradeCommand(Guid.NewGuid(),q.Quote)).Ok&&Count(s.ledger,"trade-coin")==100,"刷新后旧报价成交");bool rejected=false;try{new MerchantGoods("food",0,0,1);}catch(ArgumentException){rejected=true;}Assert(rejected,"未批准的零价");});
        Test("cross_container_currency_stable_deduction",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",6);s.ledger.Grant("safe","trade-coin",9);Assert(Buy(s.economy).Ok&&Count(s.ledger,"trade-coin")==5&&s.ledger.Items.Single(i=>i.DefinitionId=="trade-coin").Location.ContainerId=="safe","未按稳定合法容器扣款");});
        Test("failed_request_id_cannot_be_repurposed_for_other_quote",()=>{var s=Setup();var id=Guid.NewGuid();var failedQuote=s.economy.QuotePurchase("hero","shop-a","food",1,1);Assert(!s.economy.Execute(new TradeCommand(id,failedQuote.Quote)).Ok,"缺钱夹具未失败");s.ledger.Grant("team","trade-coin",30);var other=s.economy.QuotePurchase("hero","shop-a","food",2,1);Assert(!s.economy.Execute(new TradeCommand(id,other.Quote)).Ok&&Count(s.ledger,"food")==0,"失败请求ID被改作另一交易");});
        Test("malformed_equipment_payload_restore_rejected_without_replacement",()=>{var s=Setup();s.ledger.Register(new InventoryDefinition("blade",1,1,1,InventoryHand.Right));var item=new EquipmentItemState("blade-id","blade",OffhandKind.Other,5);s.ledger.Grant("team","blade",1,item);var bad=s.economy.Capture();bad.inventory.items.Single(i=>i.id=="blade-id").equipment.runtime.magazine.capacity=0;Assert(!s.economy.Restore(bad).Ok&&ReferenceEquals(s.ledger.Find("blade-id").Equipment,item),"坏装备快照部分替换活payload");});
        Test("single_inventory_success_survives_throwing_listener",()=>{var s=Setup();s.ledger.Changed+=()=>throw new Exception("bad view");var result=s.ledger.Grant("team","food",1);Assert(result.Ok&&Count(s.ledger,"food")==1,"成功Grant被UI订阅异常包装失败");});
        Test("container_seed_is_one_atomic_visible_change",()=>{var s=Setup();int notices=0;s.ledger.Changed+=()=>{notices++;Assert(s.ledger.Items.Count(i=>i.Location.ContainerId=="box")==2,"观察到半箱播种");};var result=s.ledger.CreateContainerWithItems(new InventoryContainer("box",2,1),new[]{new InventoryContainerGrant("food",1),new InventoryContainerGrant("trade-coin",1)});Assert(result.Ok&&notices==1,"整箱未一次发布");});
        Test("container_seed_failure_leaves_no_container_or_item",()=>{var s=Setup();var result=s.ledger.CreateContainerWithItems(new InventoryContainer("box",1,1),new[]{new InventoryContainerGrant("food",1),new InventoryContainerGrant("trade-coin",1)});Assert(!result.Ok&&s.ledger.Container("box")==null&&!s.ledger.Items.Any(),"播种失败留下半箱");});
        Test("changed_owner_eligibility_changes_definition_fingerprint",()=>{var source=Setup();source.ledger.Register(new InventoryDefinition("blade",1,1,1,InventoryHand.Right,owners:new[]{"hero-a"}));var target=Setup();target.ledger.Register(new InventoryDefinition("blade",1,1,1,InventoryHand.Right,owners:new[]{"hero-b"}));Assert(!target.economy.Restore(source.economy.Capture()).Ok,"角色装备资格配置变化未进入快照指纹");});
        Test("final_access_check_cannot_overwrite_new_restock_state",()=>{var s=Setup();s.ledger.Grant("team","trade-coin",30);var quote=s.economy.QuotePurchase("hero","shop-a","food",1,1);int calls=0;s.access.BeforeCheck=()=>{if(++calls==2)s.economy.Advance(30);return new CommerceAccess(true,null,1,new[]{"team","safe"},"team","team",new[]{"team","safe"});};var receipt=s.economy.Execute(new TradeCommand(Guid.NewGuid(),quote.Quote));Assert(!receipt.Ok&&Count(s.ledger,"trade-coin")==30&&s.economy.Merchant("shop-a").stock.Single(x=>x.definitionId=="food").quantity==5,"最终访问回调期间的新货架被旧候选覆盖");});
        Test("restore_rejects_overflowed_positive_x_without_live_mutation",()=>{var source=Setup();source.ledger.Grant("team","food",1);var bad=source.economy.Capture();bad.inventory.items[0].x=int.MaxValue;var target=Setup();target.ledger.Grant("team","trade-coin",7);var result=target.economy.Restore(bad);Assert(!result.Ok&&Count(target.ledger,"trade-coin")==7&&Count(target.ledger,"food")==0,"正X端点溢出使坏档覆盖活账本");});
        Test("restore_rejects_overflowed_positive_y_without_live_mutation",()=>{var source=Setup();source.ledger.Grant("team","food",1);var bad=source.economy.Capture();bad.inventory.items[0].y=int.MaxValue;var target=Setup();target.ledger.Grant("team","trade-coin",7);var result=target.economy.Restore(bad);Assert(!result.Ok&&Count(target.ledger,"trade-coin")==7&&Count(target.ledger,"food")==0,"正Y端点溢出使坏档覆盖活账本");});
        Test("explicit_move_rejects_overflow_coordinates_atomically",()=>{foreach(var position in new[]{(int.MaxValue,0),(0,int.MaxValue)}){var s=Setup();s.ledger.Grant("team","food",1);var item=s.ledger.Items[0];var result=s.ledger.Transfer(s.ledger.Plan(item.Id,"team",1,position.Item1,position.Item2));Assert(!result.Ok&&s.ledger.Find(item.Id).Location.X==0&&s.ledger.Find(item.Id).Location.Y==0,"显式移动端点溢出仍提交");}});
        Test("valid_touching_rectangles_and_right_edge_remain_legal",()=>{var s=Setup();s.ledger.Grant("team","food",1);s.ledger.Grant("team","large",1);var small=s.ledger.Items.Single(i=>i.DefinitionId=="food");var large=s.ledger.Items.Single(i=>i.DefinitionId=="large");Assert(s.ledger.Transfer(s.ledger.Plan(large.Id,"team",1,2,0)).Ok&&s.ledger.Transfer(s.ledger.Plan(small.Id,"team",1,1,0)).Ok&&s.ledger.Validate(out _),"合法边缘接触被误判重叠/越界");});
        Test("maximum_stack_auto_transfer_uses_free_cell_without_overflow",()=>{var ledger=MaximumStackFixture();ledger.Grant("team","max-stack",int.MaxValue);ledger.Grant("safe","max-stack",1);var source=ledger.Items.Single(i=>i.Location.ContainerId=="safe");var result=ledger.Transfer(ledger.Plan(source.Id,"team"));Assert(result.Ok&&ledger.Items.Length==2&&Count(ledger,"max-stack")==2147483648L&&ledger.Items.All(i=>i.Quantity>0)&&ledger.Validate(out _),"自动合堆加法溢出破坏数量，或未使用合法空位");});
        Test("maximum_stack_explicit_overfull_merge_is_atomic_rejection",()=>{var ledger=MaximumStackFixture();ledger.Grant("team","max-stack",int.MaxValue);ledger.Grant("safe","max-stack",1);var source=ledger.Items.Single(i=>i.Location.ContainerId=="safe");var target=ledger.Items.Single(i=>i.Location.ContainerId=="team");var result=ledger.Transfer(ledger.Plan(source.Id,"team",1,target.Location.X,target.Location.Y));Assert(!result.Ok&&ledger.Find(source.Id).Quantity==1&&ledger.Find(source.Id).Location.ContainerId=="safe"&&ledger.Find(target.Id).Quantity==int.MaxValue&&ledger.Validate(out _),"显式超堆加法溢出仍提交，未保留来源");});
        Test("maximum_stack_split_and_legal_remerge_conserve_exact_quantity",()=>{var ledger=MaximumStackFixture();ledger.Grant("team","max-stack",int.MaxValue);var original=ledger.Items[0];Assert(ledger.Transfer(ledger.Plan(original.Id,"safe",1)).Ok,"合法最大堆拆分失败");var split=ledger.Items.Single(i=>i.Location.ContainerId=="safe");Assert(ledger.Find(original.Id).Quantity==int.MaxValue-1&&split.Quantity==1&&split.Id!=original.Id,"最大堆拆分数量/身份错误");Assert(ledger.Transfer(ledger.Plan(split.Id,"team")).Ok&&ledger.Items.Length==1&&ledger.Find(original.Id).Quantity==int.MaxValue&&ledger.Validate(out _),"合法边界合回被误拒或数量不守恒");});
        Test("hand_slot_area_overflow_cannot_impersonate_one_cell",()=>{bool rejected=false;try{new InventoryContainer("invalid-hand",int.MaxValue,int.MaxValue,true,"hero",InventoryHand.Right);}catch(ArgumentException){rejected=true;}Assert(rejected,"手槽面积溢出成1绕过构造校验");});
        DialogueTests.Run(Test);
        Console.WriteLine($"Commerce core: {passed} passed, {failed} failed");Environment.ExitCode=failed==0?0:1;
    }
}
